package com.nimbusbill.customer.repository;
import com.nimbusbill.customer.entity.PricingOverride; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.*;
public interface PricingOverrideRepository extends JpaRepository<PricingOverride,UUID>{List<PricingOverride> findByCustomerIdOrderByEffectiveFromDesc(UUID customerId);@Query("select o from PricingOverride o where o.customer.id=:customerId and lower(o.product.productCode)=lower(:productCode) and o.active=true and o.effectiveFrom<=:date and (o.effectiveTo is null or o.effectiveTo>=:date) order by o.effectiveFrom desc,o.createdAt desc") List<PricingOverride> matching(@Param("customerId") UUID customerId,@Param("productCode") String productCode,@Param("date") LocalDate date);@Query("select count(o)>0 from PricingOverride o where o.customer.id=:customerId and o.product.id=:productId and o.active=true and o.id<>:excludeId and o.effectiveFrom<=coalesce(:effectiveTo,o.effectiveFrom) and (o.effectiveTo is null or o.effectiveTo>=:effectiveFrom)") boolean overlaps(@Param("customerId") UUID customerId,@Param("productId") UUID productId,@Param("effectiveFrom") LocalDate effectiveFrom,@Param("effectiveTo") LocalDate effectiveTo,@Param("excludeId") UUID excludeId);}
